const fs = require('fs');
const path = require('path');

const ROOT = path.resolve(__dirname, '..');
const LEXICON_DIR = path.join(ROOT, 'Corpus Forge', 'lexicons');
const FIGURES = path.join(LEXICON_DIR, 'key_figures.csv');
const CREATURES = path.join(LEXICON_DIR, 'creatures.csv');

function parseCsv(text) {
  const rows = [];
  let row = [];
  let field = '';
  let inQuotes = false;
  for (let i = 0; i < text.length; i += 1) {
    const char = text[i];
    const next = text[i + 1];
    if (char === '"' && inQuotes && next === '"') {
      field += '"';
      i += 1;
    } else if (char === '"') {
      inQuotes = !inQuotes;
    } else if (char === ',' && !inQuotes) {
      row.push(field);
      field = '';
    } else if ((char === '\n' || char === '\r') && !inQuotes) {
      if (char === '\r' && next === '\n') i += 1;
      row.push(field);
      if (row.some((value) => value.trim())) rows.push(row);
      row = [];
      field = '';
    } else {
      field += char;
    }
  }
  if (field || row.length) {
    row.push(field);
    if (row.some((value) => value.trim())) rows.push(row);
  }
  return rows;
}

function csv(value) {
  const text = String(value ?? '');
  return /[",\n\r]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text;
}

function appendRows(filePath, idColumn, rows) {
  const text = fs.readFileSync(filePath, 'utf8').trimEnd();
  const parsed = parseCsv(text);
  const header = parsed[0];
  const idIndex = header.indexOf(idColumn);
  const existing = new Set(parsed.slice(1).map((row) => row[idIndex]));
  const additions = rows
    .filter((row) => !existing.has(row[0]))
    .map((row) => row.map(csv).join(','));

  if (additions.length) {
    fs.writeFileSync(filePath, `${text}\n${additions.join('\n')}\n`);
  }
  return additions.length;
}

